<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Search, Refresh, Check, Close, Delete, Plus, Edit } from '@element-plus/icons-vue'
import { auditFriend, createFriend, deleteFriend, getAdminFriendPage, updateFriend, type AdminFriend } from '@/api/friend'
import type { PageResult } from '@/types/api'
const loading=ref(false);const rows=ref<AdminFriend[]>([]);const total=ref(0);const dialog=ref(false);const editing=ref<number|null>(null)
const query=reactive({page:1,pageSize:10,status:undefined as number|undefined});const form=reactive({name:'',url:'',avatar:'',description:'',group:'',status:0})
const label=(s:number)=>({0:'待审核',1:'已通过',2:'已拒绝'}[s]||'未知');const type=(s:number)=>s===1?'success':s===2?'danger':'warning'
async function load(){loading.value=true;try{const r:PageResult<AdminFriend>=await getAdminFriendPage(query);rows.value=r.records||[];total.value=r.total||0}finally{loading.value=false}}
function search(){query.page=1;load()};function reset(){query.status=undefined;search()}
function openForm(raw?:unknown){const row=raw as AdminFriend|undefined;editing.value=row?.id||null;Object.assign(form,row?{name:row.name,url:row.url,avatar:row.avatar||'',description:row.description||'',group:row.group||'',status:row.status}:{name:'',url:'',avatar:'',description:'',group:'',status:0});dialog.value=true}
async function save(){if(!form.name||!form.url){ElMessage.warning('请填写站点名称和地址');return}if(editing.value)await updateFriend(editing.value,form);else await createFriend(form);dialog.value=false;ElMessage.success('保存成功');load()}
async function audit(raw:unknown,status:number){const row=raw as AdminFriend;await auditFriend(row.id,status);ElMessage.success(status===1?'审核通过':'已拒绝');load()}
async function remove(raw:unknown){const row=raw as AdminFriend;await ElMessageBox.confirm('删除后友链将不可恢复，确定继续吗？','删除友链',{type:'warning'});await deleteFriend(row.id);ElMessage.success('删除成功');load()}
onMounted(load)
</script>
<template><div class="friend-list"><el-card class="filter" shadow="never"><el-form :inline="true"><el-form-item label="审核状态"><el-select v-model="query.status" clearable placeholder="全部"><el-option label="待审核" :value="0"/><el-option label="已通过" :value="1"/><el-option label="已拒绝" :value="2"/></el-select></el-form-item><el-form-item><el-button type="primary" :icon="Search" @click="search">查询</el-button><el-button :icon="Refresh" @click="reset">重置</el-button></el-form-item></el-form></el-card><el-card shadow="never"><div class="toolbar"><el-button type="primary" :icon="Plus" @click="openForm()">新增友链</el-button></div><el-table v-loading="loading" :data="rows" border stripe><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="name" label="站点名称" min-width="160"/><el-table-column prop="url" label="站点地址" min-width="220" show-overflow-tooltip/><el-table-column prop="group" label="分组" width="130"/><el-table-column prop="sort" label="排序" width="80"/><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="type(s.row.status)">{{label(s.row.status)}}</el-tag></template></el-table-column><el-table-column prop="createTime" label="申请时间" width="170"/><el-table-column label="操作" width="280" fixed="right"><template #default="s"><el-button link type="primary" :icon="Edit" @click="openForm(s.row)">编辑</el-button><el-button v-if="s.row.status!==1" link type="success" :icon="Check" @click="audit(s.row,1)">通过</el-button><el-button v-if="s.row.status!==2" link type="warning" :icon="Close" @click="audit(s.row,2)">拒绝</el-button><el-button link type="danger" :icon="Delete" @click="remove(s.row)">删除</el-button></template></el-table-column><template #empty><el-empty description="暂无友链"/></template></el-table><div class="pagination"><el-pagination v-model:current-page="query.page" v-model:page-size="query.pageSize" :total="total" :page-sizes="[10,20,50]" layout="total,sizes,prev,pager,next" @size-change="search" @current-change="load"/></div></el-card><el-dialog v-model="dialog" :title="editing?'编辑友链':'新增友链'" width="520px"><el-form label-width="90px"><el-form-item label="站点名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="站点地址"><el-input v-model="form.url"/></el-form-item><el-form-item label="头像地址"><el-input v-model="form.avatar"/></el-form-item><el-form-item label="分组"><el-input v-model="form.group"/></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<style scoped lang="scss">.friend-list{padding:16px}.filter{margin-bottom:16px}.toolbar{margin-bottom:12px}.pagination{margin-top:16px;display:flex;justify-content:flex-end}</style>
